import { rulesCoach } from '@/coach/coach'
import { getExercise } from '@/data/exercises'
import type {
  CheckIn,
  DateKey,
  DayRecord,
  Level,
  Settings,
  SessionLog,
  Severity,
} from '@/domain/types'
import { addDays, toMinutes } from '@/lib/dates'

// A week of plausible demo history, generated by running the real planner on
// scripted check-ins and then "doing" most of each plan. Clearly flagged as
// demo so it can be removed in one click.

interface Script {
  energy: Level
  pain: Severity
  painAreas: CheckIn['painAreas']
  stiffness: Severity
  stiffAreas: CheckIn['stiffAreas']
  sleep: Level
  /** How many planned items get done, and how hard they felt. */
  doFraction: number
  rpe: number
  open: string
}

const WEEK: Script[] = [
  {
    energy: 4,
    pain: 0,
    painAreas: [],
    stiffness: 2,
    stiffAreas: ['lower-back', 'hip-flexors'],
    sleep: 4,
    doFraction: 0.8,
    rpe: 6,
    open: '08:52',
  },
  {
    energy: 3,
    pain: 1,
    painAreas: ['quads'],
    stiffness: 1,
    stiffAreas: ['upper-back'],
    sleep: 3,
    doFraction: 0.75,
    rpe: 5,
    open: '09:10',
  },
  {
    energy: 2,
    pain: 1,
    painAreas: ['quads', 'glutes'],
    stiffness: 2,
    stiffAreas: ['lower-back'],
    sleep: 2,
    doFraction: 0.6,
    rpe: 4,
    open: '09:41',
  },
  {
    energy: 4,
    pain: 0,
    painAreas: [],
    stiffness: 1,
    stiffAreas: ['neck'],
    sleep: 4,
    doFraction: 1,
    rpe: 6,
    open: '08:47',
  },
  {
    energy: 5,
    pain: 0,
    painAreas: [],
    stiffness: 0,
    stiffAreas: [],
    sleep: 5,
    doFraction: 0.85,
    rpe: 7,
    open: '09:02',
  },
  {
    energy: 3,
    pain: 1,
    painAreas: ['calves'],
    stiffness: 1,
    stiffAreas: ['upper-back'],
    sleep: 3,
    doFraction: 0.5,
    rpe: 5,
    open: '10:15',
  },
  {
    energy: 4,
    pain: 0,
    painAreas: [],
    stiffness: 2,
    stiffAreas: ['hip-flexors', 'neck'],
    sleep: 4,
    doFraction: 0.8,
    rpe: 6,
    open: '08:58',
  },
]

export function buildDemoHistory(
  today: DateKey,
  settings: Settings,
): DayRecord[] {
  const days: DayRecord[] = []
  WEEK.forEach((s, i) => {
    const date = addDays(today, i - WEEK.length)
    const checkIn: CheckIn = {
      date,
      at: iso(date, s.open),
      energy: s.energy,
      pain: s.pain,
      painAreas: s.painAreas,
      stiffness: s.stiffness,
      stiffAreas: s.stiffAreas,
      sleep: s.sleep,
      timeAvailable: 'some',
      redFlags: [],
    }
    const plan = rulesCoach.getPlan({
      date,
      checkIn,
      history: days,
      settings,
      nowMinutes: toMinutes(s.open),
    })
    plan.accepted = true
    const doCount = Math.round(plan.items.length * s.doFraction)
    const sessions: SessionLog[] = []
    plan.items.forEach((item, idx) => {
      // Skip a snack here and there, not always the same one.
      const done =
        idx < doCount || (idx === plan.items.length - 1 && i % 2 === 0)
      const skip = !done && (idx + i) % 2 === 0
      if (!done && !skip) return
      const status = skip
        ? 'skipped'
        : idx === 1 && i === 2
          ? 'partial'
          : 'completed'
      item.status = status
      const durationSec =
        status === 'skipped' ? 0 : item.minutes * 60 + ((i * 7 + idx * 13) % 40)
      sessions.push({
        id: `demo-${date}-${item.id}`,
        date,
        itemId: item.id,
        kind: item.kind,
        category: item.category,
        startedAt: iso(date, item.time),
        endedAt: iso(date, item.time, Math.round(durationSec / 60)),
        durationSec,
        status,
        exercises: item.exercises.map((p, k) => {
          const ex = getExercise(p.exerciseId)
          const partialMiss = status === 'partial' && k > 0
          const reps =
            p.dose.kind === 'reps' ? p.dose.reps * (p.rounds ?? 1) : undefined
          const secs =
            p.dose.kind === 'time'
              ? p.dose.seconds * (p.rounds ?? 1)
              : undefined
          return {
            exerciseId: p.exerciseId,
            primary: ex.primary,
            intensity: ex.intensity,
            variation: 'standard' as const,
            target: p.dose,
            repsDone: status === 'skipped' || partialMiss ? undefined : reps,
            secondsDone: status === 'skipped' || partialMiss ? undefined : secs,
            status:
              status === 'skipped' || partialMiss
                ? ('skipped' as const)
                : ('done' as const),
          }
        }),
        post:
          status === 'skipped'
            ? undefined
            : {
                energy: Math.min(5, s.energy + (idx % 2)) as Level,
                painChange: 'same',
                stiffnessChange: idx % 3 === 0 ? 'better' : 'same',
                rpe:
                  item.kind === 'session' ? s.rpe + 1 : Math.max(2, s.rpe - 2),
                redFlags: [],
              },
      })
    })
    const last = sessions.filter((x) => x.status !== 'skipped').at(-1)
    days.push({
      date,
      demo: true,
      checkIn,
      plan,
      sessions,
      usage: {
        firstOpen: iso(date, s.open),
        lastInteraction: last?.endedAt ?? iso(date, s.open, 5),
        opens: 3 + ((i * 5) % 4),
        sessionsStarted: sessions.length,
      },
    })
  })
  return days
}

function iso(date: DateKey, hhmm: string, plusMinutes = 0): string {
  const [y, m, d] = date.split('-').map(Number)
  const [h, min] = hhmm.split(':').map(Number)
  return new Date(y, m - 1, d, h, min + plusMinutes).toISOString()
}
